checks:
CONSTRAINT chk_job_role_rates CHECK (
        minimum_hourly_rate > 0 AND maximum_hourly_rate >= minimum_hourly_rate
    )

CONSTRAINT chk_product_prices CHECK (
        list_price >= 0 AND unit_cost >= 0 AND list_price >= unit_cost
    )

CONSTRAINT chk_inventory_levels CHECK (
        reorder_quantity > 0 AND reorder_point >= 0
    )

CONSTRAINT chk_sale_totals CHECK (
        subtotal >= 0 AND discount_total >= 0 AND tax_total >= 0 AND grand_total >= 0
    )
